import{z as o,x as s,o as e,c as n,q as A,j as t,D as a,d as l,s as i,S as r}from"./chunks/framework.C8m1ZpeB.js";const D=JSON.parse('{"title":"优化案例研究","description":"","frontmatter":{"title":"优化案例研究","date":"2026-09-18T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/ce-optimization-cases.md","filePath":"llm/ce-optimization-cases.md","lastUpdated":1791413859000}'),p={name:"llm/ce-optimization-cases.md"};function d(C,E,c,m,h,_){const B=s("Mermaid");return e(),n("div",null,[E[2]||(E[2]=A('<h1 id="优化案例研究" tabindex="-1">优化案例研究 <a class="header-anchor" href="#优化案例研究" aria-label="Permalink to &quot;优化案例研究&quot;">​</a></h1><div class="epigraph"><p>案例不可移植，纪律可移植：每一刀成本优化，动手前先写好「砍在哪、怎么验证没有砍坏」。</p><footer>—— 据本仓库长上下文成本案例课与成本-质量曲线课的口径整理</footer></div><p><a href="/llm/ce-unit-economics-case">上一课</a>算全了文档问答产品的每请求账，并按作用账目排好了杠杆次序。本课把杠杆放进两个案例里兑现：一个检索型、一个低延迟型，流量画像相反，杠杆组合也不同。案例的价值不在数字——数字不迁移——在流程：先测后动、过门禁再放量。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>成本优化的失败很少是「没找到杠杆」，更多是两种：乱序与不验证。乱序：先上量化再想缓存，优化了常数、放过了数量级项；不验证：省下三成成本，质量门禁没跑，两周后客诉上门，回滚时连「哪一刀砍坏的」都说不清。缺口是两个带完整流程的案例，让排序纪律与验证纪律有可对照的样本。</p><p><span class="marginnote">术语翻译：「质量门禁」就是一组跑在每次改动前后的自动评测，像机场安检——分数没过线，改动进不了生产。它把「感觉没变差」换成可执行的数字判据，是成本优化敢动手的前提。</span></p><h3 id="案例-a-客服机器人" tabindex="-1">案例 A：客服机器人 <a class="header-anchor" href="#案例-a-客服机器人" aria-label="Permalink to &quot;案例 A：客服机器人&quot;">​</a></h3><p>基线：每次请求全量 prefill 系统提示加知识段，全量走大模型。三步改造。第一步缓存：稳定段（系统提示、工具定义、知识库固定段）前置、用户上下文后置，命中率从零做到六成——作用于 prefill 重复量，是数量级项。第二步路由：难度标注后，简单咨询（七成）进小模型，困难单留大模型，打分器按「漏检率优先」调参——作用于单价谱。第三步 KV 8-bit：容量与带宽各兑现一部分。三步各降多少入各人的账，合计每请求成本降约七成；每步之间跑分任务族质量门禁，通过才放量——流程与<a href="/llm/lc-cost-case">长上下文成本案例课</a>的六步链同构。</p><p><span class="marginnote">数字实例：三步杠杆是相乘不是相加——例如 0.5（缓存后）× 0.5（路由后）× 0.8（量化后）≈ 0.2，成本只剩两成。相乘之所以成立，是因为各杠杆作用在不同的账目上（重复量、单价谱、字节），彼此几乎不冲销。</span></p><h3 id="案例-b-代码补全" tabindex="-1">案例 B：代码补全 <a class="header-anchor" href="#案例-b-代码补全" aria-label="Permalink to &quot;案例 B：代码补全&quot;">​</a></h3><p>画像相反：输入短、输出短、QPS 高、单请求价值低。杠杆组合因此不同：第一步重钉 SLO——补全场景用户对稍高的 TPOT 不敏感，把延迟预算松一档，批工作点上移，打满率抬升（批课的「SLO 内最大批」）；第二步租法分层——基线走预留扛住水位，评测跑批与候选生成走竞价（上一课的可中断标签）；第三步才考虑权重量化——先实测瓶颈账再动手。合计单价降约六成，首 token 延迟反而因打满率结构改善而更稳。</p>',11)),(e(),t(r,null,{default:a(()=>[i(B,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20CASE%5B%22%E4%BC%98%E5%8C%96%E5%89%8D%EF%BC%9A%E9%92%89%E7%94%BB%E5%83%8F%E4%B8%8E%E5%9F%BA%E7%BA%BF%22%5D%20--%3E%20STEP%5B%22%E6%8C%89%E6%95%B0%E9%87%8F%E7%BA%A7%E6%8E%92%E6%9D%A0%E6%9D%86%22%5D%0A%20%20STEP%20--%3E%20A1%5B%22A%EF%BC%9A%E7%BC%93%E5%AD%98%200%E2%86%920.6%22%5D%0A%20%20A1%20--%3E%20G1%7B%22%E8%B4%A8%E9%87%8F%E9%97%A8%E7%A6%81%22%7D%0A%20%20G1%20--%3E%7C%E8%BF%87%7C%20A2%5B%22A%EF%BC%9A%E8%B7%AF%E7%94%B1%2070%25%20%E8%BF%9B%E5%B0%8F%E6%A8%A1%E5%9E%8B%22%5D%0A%20%20A2%20--%3E%20G2%7B%22%E8%B4%A8%E9%87%8F%E9%97%A8%E7%A6%81%22%7D%0A%20%20G2%20--%3E%7C%E8%BF%87%7C%20A3%5B%22A%EF%BC%9AKV%208-bit%22%5D%0A%20%20STEP%20--%3E%20B1%5B%22B%EF%BC%9A%E9%87%8D%E9%92%89%20SLO%20%E6%8A%AC%E6%89%B9%22%5D%0A%20%20B1%20--%3E%20B2%5B%22B%EF%BC%9A%E9%A2%84%E7%95%99%20%2B%20%E7%AB%9E%E4%BB%B7%E5%88%86%E5%B1%82%22%5D%0A%20%20A3%20--%3E%20SUM%5B%22%E4%B8%89%E5%88%97%E8%A1%A8%E6%94%B6%E8%B4%A6%EF%BC%9A%E6%88%90%E6%9C%AC%2F%E5%BB%B6%E8%BF%9F%2F%E8%B4%A8%E9%87%8F%22%5D%0A%20%20B2%20--%3E%20SUM%0A"})]),fallback:a(()=>[...E[0]||(E[0]=[l(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=A('<h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>两个案例共用的流程沉淀为四条纪律。先测后动：每一步之前把当前三列表（成本、延迟、质量）钉下来，没有基线的优化没法归因。数量级优先：先做改变请求形状与单价谱的杠杆（缓存、路由），再做改字节的（量化），最后做改摊薄的（批、租法）——上一课排序的执行版。门禁前置：质量门禁不是上线后的补救，是放量的前置条件；工作点选在<a href="/llm/dec-cost-quality-curve">成本-质量曲线课</a>的悬崖之前，每一档曲线用对应任务族的度量。回滚有触发线：门禁分数跌破哪条线自动回滚，写进合同（下一课的条款）。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>为什么流程比数字重要：案例数字是画像、报价、模型代际的函数，三者一变全变；而「测、排、砍、验」的流程对任何画像成立。排序的机制根据在第一课的账目分解：数量级项改账的结构，常数项改账的系数——先改结构后改系数，不把精力花在已经不大的项上。验证纪律的机制根据在质量与成本的合同关系：成本收益即时入账、质量损失延迟显现，没有前置门禁，两者的时序差会让每一刀都「看起来赚了」。</p>',4)),(e(),t(r,null,{default:a(()=>[i(B,{id:"mermaid-44",class:"mermaid",graph:"flowchart%20LR%0A%20%20CUT%5B%22%E7%AC%AC%20N%20%E5%88%80%E4%BC%98%E5%8C%96%E4%B8%8A%E7%BA%BF%22%5D%20--%3E%20C1%5B%22%E6%88%90%E6%9C%AC%E5%8F%98%E5%8C%96%EF%BC%9A%E5%BD%93%E5%91%A8%E5%85%A5%E8%B4%A6%22%5D%0A%20%20CUT%20--%3E%20C2%5B%22%E8%B4%A8%E9%87%8F%E5%8F%98%E5%8C%96%EF%BC%9A%E6%95%B0%E5%91%A8%E5%90%8E%E6%89%8D%E6%98%BE%E7%8E%B0%22%5D%0A%20%20C1%20--%3E%20ASY%5B%22%E6%97%B6%E5%BA%8F%E5%B7%AE%EF%BC%9A%E6%97%A0%E9%97%A8%E7%A6%81%E6%97%B6%E6%AF%8F%E5%88%80%E9%83%BD%E7%9C%8B%E4%BC%BC%E8%B5%9A%E4%BA%86%22%5D%0A%20%20C2%20--%3E%20ASY%0A%20%20ASY%20--%3E%20BAD%5B%22%E5%AE%A2%E8%AF%89%E4%B8%8A%E9%97%A8%E6%89%8D%E5%9B%9E%E6%BB%9A%EF%BC%8C%E5%BD%92%E5%9B%A0%E5%9B%B0%E9%9A%BE%22%5D%0A%20%20BAD%20--%3E%20GATE%5B%22%E5%89%8D%E7%BD%AE%E9%97%A8%E7%A6%81%EF%BC%9A%E8%B7%8C%E7%A0%B4%E8%A7%A6%E5%8F%91%E7%BA%BF%E4%B8%8D%E6%94%BE%E9%87%8F%22%5D%0A%20%20GATE%20-.-%3E%20CUT%0A"})]),fallback:a(()=>[...E[1]||(E[1]=[l(" Loading... ",-1)])]),_:1})),E[4]||(E[4]=A('<p><span class="marginnote">案例 A 的一个易错点：路由上线后同前缀请求被打散到两档模型，前缀缓存命中率跌了约一成——缓存与路由两本账必须合算，联合调参后命中回升。单杠杆优化的账，经常被另一个杠杆吃掉一块。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>案例未覆盖检索栈（嵌入与索引侧）与训练侧的成本，那两块账在各自课程里。数字全部是量级演示，不可作为决策依据；机制与流程可迁移，迁移时四条纪律一条不能省。案例 A 的路由漏检率依赖难度标注的质量，标注贵的业务这条杠杆要先算标注成本。最后，两案例都假设模型代际稳定——换代触发全链路重测，这是合同条款，不是自觉。</p><p><span class="marginnote">直觉类比：路由的难度标注像分诊前的化验单——化验便宜且准，分诊就省钱；若化验本身比看病还贵，就得先算化验的成本。标注贵的业务想上路由杠杆，先把标注这道成本算清楚再决定。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>两个画像相反的案例：检索型靠缓存与路由（数量级项），低延迟型靠 SLO 重钉与租法分层。</li><li>四条纪律：先测后动、数量级优先、门禁前置、回滚有触发线。</li><li>先改账的结构（少算、共享、谱系），再改账的系数（字节、摊薄）。</li><li>杠杆之间互相牵制（路由与缓存、量化与级联），账要合算。</li><li>出处：流程与门禁口径见本仓库长上下文成本案例课、成本-质量曲线课；案例数字为量级演示。</li></ul>',6))])}const u=o(p,[["render",d]]);export{D as __pageData,u as default};
